import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

export function packContext(sections, maxBytes) {
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) {
    throw new Error('maxBytes must be a nonnegative safe integer');
  }
  if (!Array.isArray(sections)) {
    throw new Error('sections must be a dense array');
  }

  const ids = new Set();
  const entries = [];
  for (let index = 0; index < sections.length; index += 1) {
    if (!Object.hasOwn(sections, index)) {
      throw new Error('sections must not contain missing slots');
    }
    const section = sections[index];
    if (section === null || typeof section !== 'object' || Array.isArray(section)) {
      throw new Error('Each section must be an object');
    }
    const { id, text, priority, required } = section;
    if (typeof id !== 'string' || id.length === 0 ||
        typeof text !== 'string' ||
        !Number.isSafeInteger(priority) || priority < 0 ||
        typeof required !== 'boolean') {
      throw new Error('Invalid section fields');
    }
    if (ids.has(id)) throw new Error('Duplicate section ID');
    ids.add(id);
    entries.push({ id, text, priority, required, index });
  }

  // Validate every entry before considering any budget-dependent decision.
  for (const entry of entries) {
    entry.frame = '### ' + JSON.stringify(entry.id) + '\n' + entry.text + '\n';
    entry.cost = Buffer.byteLength(entry.frame, 'utf8');
  }
  let remaining = maxBytes;
  const selected = [];
  const includedIds = new Set();
  const include = (entry) => {
    remaining -= entry.cost;
    selected.push(entry);
    includedIds.add(entry.id);
  };
  for (const entry of entries) {
    if (!entry.required) continue;
    if (entry.cost > remaining) {
      throw new Error('Required sections exceed maxBytes');
    }
    include(entry);
  }
  const optional = entries.filter(entry => !entry.required);
  optional.sort((a, b) => b.priority - a.priority || a.index - b.index);
  for (const entry of optional) {
    if (entry.cost <= remaining) include(entry);
  }
  const text = selected.map(entry => entry.frame).join('');
  return {
    text,
    bytes: Buffer.byteLength(text, 'utf8'),
    included: selected.map(entry => entry.id),
    omitted: entries.filter(entry => !entry.required && !includedIds.has(entry.id))
      .map(entry => entry.id),
  };
}

function main() {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node context-packet.js INPUT_JSON_FILE');
    const input = JSON.parse(readFileSync(process.argv[2], 'utf8'));
    if (input === null || typeof input !== 'object' || Array.isArray(input)) {
      throw new Error('Input JSON must be an object');
    }
    const result = packContext(input.sections, input.maxBytes);
    process.stdout.write(JSON.stringify(result) + '\n');
  } catch (error) {
    process.stderr.write((error instanceof Error ? error.message : String(error)) + '\n');
    process.exitCode = 2;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main();
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { packContext } from '../context-packet.js';

const section = (id, text = '', priority = 0, required = false) =>
  ({ id, text, priority, required });
const frame = s => '### ' + JSON.stringify(s.id) + '\n' + s.text + '\n';
const cost = s => Buffer.byteLength(frame(s), 'utf8');

test('safe integer boundaries and strict input validation, including omitted entries', () => {
  const max = Number.MAX_SAFE_INTEGER;
  assert.deepEqual(packContext([], max), { text: '', bytes: 0, included: [], omitted: [] });
  assert.deepEqual(packContext([section('max', '', max)], max).included, ['max']);
  for (const value of [-1, 0.5, max + 1, NaN, Infinity, '0', null, undefined, true, 0n]) {
    assert.throws(() => packContext([], value), Error);
    assert.throws(() => packContext([{ ...section('bad'), priority: value }], 0), Error);
  }
  for (const value of [null, undefined, {}, 'x', new Array(2), [null], [[]], [1]]) {
    assert.throws(() => packContext(value, 0), Error);
  }
  const invalidFields = {
    id: ['', 1, null, undefined],
    text: [1, null, undefined, new String('text')],
    required: [0, 1, 'false', null, undefined],
  };
  for (const [key, values] of Object.entries(invalidFields)) {
    for (const value of values) {
      assert.throws(() => packContext([section('valid'), { ...section('bad'), [key]: value }], 0), Error);
    }
  }
  for (const key of ['id', 'text', 'priority', 'required']) {
    const missing = section('missing');
    delete missing[key];
    assert.throws(() => packContext([missing], 0), Error);
  }
  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
});

test('exact escaping, UTF-8, whitespace, special IDs, and immutable inputs', () => {
  const sections = ['__proto__', 'A', 'a', ' ', '雪\n\u0000"\\', '\ud800']
    .map(id => Object.freeze({ ...section(id, ' é\r\n雪\ud800 ', 0, true), extra: 42 }));
  Object.freeze(sections);
  const text = sections.map(frame).join('');
  const bytes = Buffer.byteLength(text, 'utf8');
  assert.deepEqual(packContext(sections, bytes), {
    text, bytes, included: sections.map(s => s.id), omitted: [],
  });
  assert.throws(() => packContext(sections, bytes - 1), Error);
});

test('required input order, optional stable priority order, skip and original omission order', () => {
  const sections = [
    section('low-large', 'x'.repeat(100), 0),
    section('tie-first', '', 4),
    section('required-first', '', 0, true),
    section('high-large', 'x'.repeat(100), 10),
    section('high-small', '', 9),
    section('required-last', '', 100, true),
    section('tie-last', '', 4),
    section('no-room', '', 1),
  ];
  const selected = [sections[2], sections[5], sections[4], sections[1], sections[6]];
  const bytes = selected.reduce((total, s) => total + cost(s), 0);
  assert.deepEqual(packContext(sections, bytes), {
    text: selected.map(frame).join(''), bytes,
    included: selected.map(s => s.id),
    omitted: ['low-large', 'high-large', 'no-room'],
  });
});

test('CLI success, import isolation, and failures have exact stream and status contracts', () => {
  const dir = mkdtempSync(join(tmpdir(), 'context-packet-test-'));
  const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  const fails = args => {
    const result = run(args);
    assert.equal(result.error, undefined);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  };
  try {
    const input = join(dir, 'input.json');
    const sections = [section('雪', 'é', 0, true)];
    const maxBytes = cost(sections[0]);
    writeFileSync(input, JSON.stringify({ sections, maxBytes, ignored: true }));
    const result = run([input]);
    assert.equal(result.error, undefined);
    assert.equal(result.status, 0);
    assert.equal(result.stderr, '');
    assert.equal(result.stdout, JSON.stringify(packContext(sections, maxBytes)) + '\n');
    fails([]);
    fails([input, 'extra']);
    fails([join(dir, 'missing.json')]);
    fails([dir]);
    for (const contents of ['{', 'null', '[]', '{}',
      JSON.stringify({ sections, maxBytes: 0 }),
      JSON.stringify({ sections: [{ ...section('x'), required: 1 }], maxBytes: 0 }),
      JSON.stringify({ sections: [], maxBytes: Number.MAX_SAFE_INTEGER + 1 })]) {
      writeFileSync(input, contents);
      fails([input]);
    }
    const imported = spawnSync(process.execPath,
      ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)};`],
      { encoding: 'utf8' });
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

