+    text: [1, null, undefined, new String('text')],
+    required: [0, 1, 'false', null, undefined],
+  };
+  for (const [key, values] of Object.entries(invalidFields)) {
+    for (const value of values) {
+      assert.throws(() => packContext([section('valid'), { ...section('bad'), [key]: value }], 0), Error);
+    }
+  }
+  for (const key of ['id', 'text', 'priority', 'required']) {
+    const missing = section('missing');
+    delete missing[key];
+    assert.throws(() => packContext([missing], 0), Error);
+  }
+  assert.throws(() => packContext([section('__proto__'), section('__proto__')], 0), Error);
+});
+
+test('exact escaping, UTF-8, whitespace, special IDs, and immutable inputs', () => {
+  const sections = ['__proto__', 'A', 'a', ' ', '雪\n\u0000"\\', '\ud800']
+    .map(id => Object.freeze({ ...section(id, ' é\r\n雪\ud800 ', 0, true), extra: 42 }));
+  Object.freeze(sections);
+  const text = sections.map(frame).join('');
+  const bytes = Buffer.byteLength(text, 'utf8');
+  assert.deepEqual(packContext(sections, bytes), {
+    text, bytes, included: sections.map(s => s.id), omitted: [],
+  });
+  assert.throws(() => packContext(sections, bytes - 1), Error);
+});
+
+test('required input order, optional stable priority order, skip and original omission order', () => {
+  const sections = [
+    section('low-large', 'x'.repeat(100), 0),
+    section('tie-first', '', 4),
+    section('required-first', '', 0, true),
+    section('high-large', 'x'.repeat(100), 10),
+    section('high-small', '', 9),
+    section('required-last', '', 100, true),
+    section('tie-last', '', 4),
+    section('no-room', '', 1),
+  ];
+  const selected = [sections[2], sections[5], sections[4], sections[1], sections[6]];
+  const bytes = selected.reduce((total, s) => total + cost(s), 0);
+  assert.deepEqual(packContext(sections, bytes), {
+    text: selected.map(frame).join(''), bytes,
+    included: selected.map(s => s.id),
+    omitted: ['low-large', 'high-large', 'no-room'],
+  });
+});
+
+test('CLI success, import isolation, and failures have exact stream and status contracts', () => {
+  const dir = mkdtempSync(join(tmpdir(), 'context-packet-test-'));
+  const cli = fileURLToPath(new URL('../context-packet.js', import.meta.url));
+  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
+  const fails = args => {
+    const result = run(args);
+    assert.equal(result.error, undefined);
+    assert.equal(result.status, 2);
+    assert.equal(result.stdout, '');
+    assert.ok(result.stderr.length > 0);
+  };
+  try {
+    const input = join(dir, 'input.json');
+    const sections = [section('雪', 'é', 0, true)];
+    const maxBytes = cost(sections[0]);
+    writeFileSync(input, JSON.stringify({ sections, maxBytes, ignored: true }));
+    const result = run([input]);
+    assert.equal(result.error, undefined);
+    assert.equal(result.status, 0);
+    assert.equal(result.stderr, '');
+    assert.equal(result.stdout, JSON.stringify(packContext(sections, maxBytes)) + '\n');
+    fails([]);
+    fails([input, 'extra']);
+    fails([join(dir, 'missing.json')]);
+    fails([dir]);
+    for (const contents of ['{', 'null', '[]', '{}',
+      JSON.stringify({ sections, maxBytes: 0 }),
+      JSON.stringify({ sections: [{ ...section('x'), required: 1 }], maxBytes: 0 }),
+      JSON.stringify({ sections: [], maxBytes: Number.MAX_SAFE_INTEGER + 1 })]) {
+      writeFileSync(input, contents);
+      fails([input]);
+    }
+    const imported = spawnSync(process.execPath,
+      ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../context-packet.js', import.meta.url).href)};`],
+      { encoding: 'utf8' });
+    assert.equal(imported.status, 0);
+    assert.equal(imported.stdout, '');
+    assert.equal(imported.stderr, '');
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});

